int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    char *S = (char*)malloc((3 * N + 5) * sizeof(char));
    scanf("%s", S);

    int M = 3 * N;

    /* dp over prefixes:
       dp[i][r][g][b] compressed by observing:
       after processing prefix, unmatched balls can only be of at most two colors,
       and optimality corresponds to noncrossing interval matching.

       We use a stack-like DP on counts of currently open groups by color pair.
       A simpler equivalent formulation:
       process IDs left to right, and whenever we decide triples minimizing sum(c-a),
       each triple corresponds to matching one ball with the nearest possible pair structure.

       This can be counted by interval DP:
       Let f[l][r] = number of optimal ways for substring [l..r] (1-indexed, odd length multiple of 3),
       where the substring contains equal numbers of R,G,B and is partitioned optimally internally.
       Transition: l is grouped with some m,k (l<m<k), colors all distinct, and
       subintervals [l+1..m-1], [m+1..k-1], [k+1..r] are each balanced.
       For optimality, total cost equals minimum possible, which is achieved iff no crossings,
       so this Catalan-like DP works together with global minimum-cost property.

       To make it efficient, use memoization with balance pruning.
       Constraints in the original problem allow O((3N)^3) with pruning only for small/medium N.
       Here we implement O(M^3), sufficient for intended constraints.
    */

    /* prefix counts */
    int *pr = (int*)calloc(M + 1, sizeof(int));
    int *pg = (int*)calloc(M + 1, sizeof(int));
    int *pb = (int*)calloc(M + 1, sizeof(int));

    for (int i = 1; i <= M; i++) {
        pr[i] = pr[i - 1];
        pg[i] = pg[i - 1];
        pb[i] = pb[i - 1];
        if (S[i - 1] == 'R') pr[i]++;
        else if (S[i - 1] == 'G') pg[i]++;
        else pb[i]++;
    }

    auto int balanced(int l, int r) {
        if (l > r) return 1;
        int cr = pr[r] - pr[l - 1];
        int cg = pg[r] - pg[l - 1];
        int cb = pb[r] - pb[l - 1];
        return cr == cg && cg == cb;
    }

    long long **dp = (long long**)malloc((M + 2) * sizeof(long long*));
    for (int i = 0; i <= M + 1; i++) {
        dp[i] = (long long*)calloc(M + 2, sizeof(long long));
    }

    for (int i = 1; i <= M + 1; i++) dp[i][i - 1] = 1; /* empty interval */

    for (int len = 3; len <= M; len += 3) {
        for (int l = 1; l + len - 1 <= M; l++) {
            int r = l + len - 1;
            if (!balanced(l, r)) continue;

            long long ways = 0;
            for (int m = l + 1; m <= r - 1; m++) {
                for (int k = m + 1; k <= r; k++) {
                    char c1 = S[l - 1], c2 = S[m - 1], c3 = S[k - 1];
                    if (c1 == c2 || c1 == c3 || c2 == c3) continue;
                    if (!balanced(l + 1, m - 1)) continue;
                    if (!balanced(m + 1, k - 1)) continue;
                    if (!balanced(k + 1, r)) continue;

                    long long add = dp[l + 1][m - 1];
                    add = add * dp[m + 1][k - 1] % MOD;
                    add = add * dp[k + 1][r] % MOD;
                    ways += add;
                    if (ways >= MOD) ways -= MOD;
                }
            }
            dp[l][r] = ways;
        }
    }

    /* People are unlabeled by sets only; the interval DP already counts set partitions uniquely.
       No extra factorial factor is needed. */
    printf("%lld\n", dp[1][M] % MOD);

    for (int i = 0; i <= M + 1; i++) free(dp[i]);
    free(dp);
    free(pr);
    free(pg);
    free(pb);
    free(S);
    return 0;
}

